From 4d248a205f0a5c7c903f535004831bc3d0678c04 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:14:26 +0100
Subject: [PATCH] KIconUtils: allow sizing overlays for a given icon size

addOverlays() chose the overlay size from the size the icon is painted
at, so previews of different aspect ratios shown at the same icon size
got emblems of different sizes. Add an overload that takes that size.

BUG: 499363
---
 src/util/kiconutils.cpp | 21 +++++++++++++++------
 src/util/kiconutils.h   | 12 ++++++++++++
 2 files changed, 27 insertions(+), 6 deletions(-)

diff --git a/src/util/kiconutils.cpp b/src/util/kiconutils.cpp
index 318da0c..4c7998d 100644
--- a/src/util/kiconutils.cpp
+++ b/src/util/kiconutils.cpp
@@ -19,7 +19,7 @@ class KOverlayIconEngine : public QIconEngine
 public:
     KOverlayIconEngine(const QIcon &icon, const QIcon &overlay, Qt::Corner position);
     KOverlayIconEngine(const QIcon &icon, const QHash<Qt::Corner, QIcon> &overlays);
-    KOverlayIconEngine(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition);
+    KOverlayIconEngine(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition, const QSize &iconSize);
     void paint(QPainter *painter, const QRect &rect, QIcon::Mode mode, QIcon::State state) override;
     QIconEngine *clone() const override;

@@ -34,6 +34,7 @@ public:
 private:
     QIcon m_base;
     QHash<Qt::Corner, QIcon> m_overlays;
+    QSize m_iconSize;
 };

 KOverlayIconEngine::KOverlayIconEngine(const QIcon &icon, const QIcon &overlay, Qt::Corner position)
@@ -50,9 +51,10 @@ KOverlayIconEngine::KOverlayIconEngine(const QIcon &icon, const QHash<Qt::Corner
 {
 }

-KOverlayIconEngine::KOverlayIconEngine(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition)
+KOverlayIconEngine::KOverlayIconEngine(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition, const QSize &iconSize)
     : QIconEngine()
     , m_base(icon)
+    , m_iconSize(iconSize)
 {
     const std::array<Qt::Corner, 4> indexToCorner{
         Qt::BottomRightCorner,
@@ -151,7 +153,9 @@ void KOverlayIconEngine::paint(QPainter *painter, const QRect &rect, QIcon::Mode
     const int top = iconRect.top();
     const int width = iconRect.width();
     const int height = iconRect.height();
-    const int iconSize = qMin(width, height);
+    // Size the overlays for the requested icon size if there is one, so that they don't
+    // depend on the aspect ratio of the base icon (e.g. a preview).
+    const int iconSize = m_iconSize.isValid() ? qMin(m_iconSize.width(), m_iconSize.height()) : qMin(width, height);
     // Determine the overlay icon size
     int overlaySize;
     if (iconSize < 32) {
@@ -168,7 +172,7 @@ void KOverlayIconEngine::paint(QPainter *painter, const QRect &rect, QIcon::Mode
         overlaySize = (int)(iconSize / 4);
     }
     // Never let the overlay be larger than the icon it is drawn on.
-    overlaySize = qMin(overlaySize, iconSize);
+    overlaySize = qMin(overlaySize, qMin(width, height));

     // Iterate over stored overlays
     QHash<Qt::Corner, QIcon>::const_iterator i = m_overlays.constBegin();
@@ -216,13 +220,18 @@ QIcon addOverlays(const QIcon &icon, const QHash<Qt::Corner, QIcon> &overlays)
     return QIcon(new KOverlayIconEngine(icon, overlays));
 }

-QIcon addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition)
+QIcon addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition, const QSize &iconSize)
 {
     if (overlays.count() == 0) {
         return icon;
     }

-    return QIcon(new KOverlayIconEngine(icon, overlays, startPosition));
+    return QIcon(new KOverlayIconEngine(icon, overlays, startPosition, iconSize));
+}
+
+QIcon addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition)
+{
+    return addOverlays(icon, overlays, startPosition, QSize());
 }

 QIcon addOverlays(const QIcon &icon, const QStringList &overlays)
diff --git a/src/util/kiconutils.h b/src/util/kiconutils.h
index a7b616d..8d8fc4d 100644
--- a/src/util/kiconutils.h
+++ b/src/util/kiconutils.h
@@ -77,6 +77,18 @@ KGUIADDONS_EXPORT QIcon addOverlays(const QIcon &icon, const QStringList &overla
  */
 KGUIADDONS_EXPORT QIcon addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition);

+/*!
+ * \overload addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition)
+ *
+ * The overlays are sized for an icon of \a iconSize instead of the size the icon is
+ * painted at, so that icons with different aspect ratios (e.g. previews) shown at the
+ * same icon size get overlays of the same size. An overlay is never larger than the
+ * painted icon.
+ *
+ * \since 6.33
+ */
+KGUIADDONS_EXPORT QIcon addOverlays(const QIcon &icon, const QStringList &overlays, Qt::Corner startPosition, const QSize &iconSize);
+
 /*!
  * Adds up to four overlays on the icon constructed from \a iconName.
  *
-- 
